e=np.asarray(df['eps']);T=np.asarray(df['T']);s=np.asarray(df['sigma'])
fams={
 'voce_T3': lambda p: p[0]*T**3 + p[1]*(1-np.exp(-p[2]*e)) + p[3]*e**2 + p[4]*e**3*T**p[5],
 'exp_mix': lambda p: p[0]*T**3 + p[1]*e**2 + p[2]*e**p[3]*np.exp(p[4]*T) + p[5]*e*T**p[6],
 'powmix': lambda p: p[0]*T**p[1] + p[2]*e**p[3]*T**p[4] + p[5]*e**p[6] + p[7]*e**p[8]*T**p[9],
}
rng=np.random.default_rng(3)
for name,f in fams.items():
    best=None
    npar=10
    for k in range(40):
        p0=rng.normal(0,1,npar); p0[[2,3,5,6,8,9]]=np.abs(p0[[2,3,5,6,8,9]])*2+0.5
        if name=='voce_T3': p0=np.concatenate([rng.normal(0,1,5),[2.0]])
