        try:
            r=least_squares(lambda p: f(p)-s, p0, max_nfev=300)
            c=np.mean(r.fun**2)/np.var(s)
            if np.isfinite(c) and (best is None or c<best[0]): best=(c,np.round(r.x,4).tolist())
